import{_ as w,C as s,o as u,c as g,j as t,a,E as n,a8 as m}from"./chunks/framework.27XeWUA0.js";const o="/schedule-dashboard/thumbs/yt/AnsXWH2_EBU-640.webp",b="/schedule-dashboard/thumbs/yt/AnsXWH2_EBU-1280.webp",r="/schedule-dashboard/thumbs/yt/UW8Qkk7MG8A-640.webp",v="/schedule-dashboard/thumbs/yt/UW8Qkk7MG8A-1280.webp",i="/schedule-dashboard/thumbs/yt/P_0_Th_ZzIg-640.webp",k="/schedule-dashboard/thumbs/yt/P_0_Th_ZzIg-1280.webp",l="/schedule-dashboard/thumbs/yt/58ulJViGFgU-640.webp",f="/schedule-dashboard/thumbs/yt/58ulJViGFgU-1280.webp",h="/schedule-dashboard/thumbs/yt/xZX3pmaB8Hk-640.webp",y="/schedule-dashboard/thumbs/yt/xZX3pmaB8Hk-1280.webp",c="/schedule-dashboard/thumbs/yt/SbwckhZkPGs-640.webp",_="/schedule-dashboard/thumbs/yt/SbwckhZkPGs-1280.webp",X=JSON.parse('{"title":"AI Digest · Thu 29 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-29","routine":"digest"},"relativePath":"digest/2026-10-29.md","filePath":"digest/[date].md"}'),A={name:"digest/2026-10-29.md"},S=o+" 640w, "+b+" 1280w",I=r+" 640w, "+v+" 1280w",P=i+" 640w, "+k+" 1280w",x=l+" 640w, "+f+" 1280w",T=h+" 640w, "+y+" 1280w",B=c+" 640w, "+_+" 1280w",H={id:"ai-digest-·-thu-29-oct-2026",tabindex:"-1"};function U(G,e,Z,E,M,W){const d=s("Badge"),p=s("DayFilter");return u(),g("div",null,[t("h1",H,[e[0]||(e[0]=a("AI Digest · Thu 29 Oct 2026 ",-1)),n(d,{type:"tip",text:"6"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-thu-29-oct-2026","aria-label":'Permalink to "AI Digest · Thu 29 Oct 2026 <Badge type="tip" text="6" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 29 Oct 2026 · run date Thu 29 Oct 2026 · 6 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(" 5 new talks in the last 24 hours, all with full transcripts, and it's a security-heavy day. The freshest is Sonar's conversation with Addy Osmani (29 Oct, 4:30 AM IST) on how Anthropic went from about 2,500 to 30,000 merged changes a day, a skim for its review workflow. The pick is Patrick Smyth's Chainguard talk, with fresh attack data (exploits now land about 70 days before patches) and the claim that about 5% of upstream agent skills are malicious. Sonar's Hunter Agent demo and Runpod's vLLM benchmarking talk are skims, and Keycard's agent auth talk is mostly a repeat of its two earlier talks, apart from a useful SDK-versus-gateway comparison.")]),t("p",null,[t("strong",null,"Better Stack:"),a(" 1 new video, a short hands-on test of NVIDIA's OpenShell agent sandbox (28 Oct, 7:30 PM IST). Agent sandboxes are well covered, but its per-request network rules and credential injection are new and worth the 8 minutes.")])],-1)),n(p),e[5]||(e[5]=m('<div class="grid cards2"><article class="it full" id="v-AnsXWH2_EBU" data-title="How Anthropic Merges 30,000 Code Changes a Day - Manish Kapur, Sonar &amp; Addy Osmani, Anthropic" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=AnsXWH2_EBU" target="_blank" rel="noopener"><img src="'+o+'" srcset="'+S+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=AnsXWH2_EBU" target="_blank" rel="noopener">How Anthropic Merges 30,000 Code Changes a Day - Manish Kapur, Sonar &amp; Addy Osmani, Anthropic</a></h3><div class="meta">AI Engineer · Manish Kapur (Sonar) in conversation with Addy Osmani (Anthropic) · uploaded 29 Oct, 4:30 AM IST · 18:53</div><div class="verdict v-skim"><b>Verdict:</b> skim from 6:13 — the Anthropic review workflow (6:13–8:20) is the new part; the rest is Sonar&#39;s familiar layered-verification pitch.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 24 times before (and this is Sonar&#39;s fifth talk on it). New here: Anthropic&#39;s own numbers and review loop, from about 2,500 merged changes a day in May to about 30,000 now.</div><div class="repeat">🔁 Repeat: &#39;software factory&#39; — seen 11 times before. New here: Addy Osmani&#39;s own &quot;lights-on&quot; versus &quot;dark&quot; factory definitions and his prediction for 2027.</div><div class="repeat">🔁 Repeat: &#39;coding agents in production&#39; — seen 49 times before. New here: fresh stats from Sonar&#39;s upcoming State of Code survey of 1,000+ developers.</div><div class="sh">The verification gap</div><ul><li><strong>Throughput up, merges failing:</strong> CircleCI analysed 28 million CI workflows this year and found throughput up about 59%, yet three in ten attempts to merge into production fail (<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=117s" target="_blank" rel="noopener">1:57</a>–<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=148s" target="_blank" rel="noopener">2:28</a>)</li><li><strong>Light versus dark factories:</strong> Osmani defines a software factory as &quot;harnessing loops at scale&quot;. In a lights-on factory agents plan, build, check and ship while a person still applies judgment and taste. In a dark factory the person moves up to stating intent and is pulled in only for rare exceptions (<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=168s" target="_blank" rel="noopener">2:48</a>–<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=228s" target="_blank" rel="noopener">3:48</a>)</li><li><strong>Survey numbers:</strong> 85% of organisations already use coding agents, and 76% of developers using AI code say it&#39;s produced faster than they can verify. In Sonar&#39;s survey 84% say AI ships features faster, PRs are getting larger, 5% of companies run software factories today (34% expect to, 39% in financial services), and 28% have approved agents with shared controls (<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=231s" target="_blank" rel="noopener">3:51</a>–<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=256s" target="_blank" rel="noopener">4:16</a>), (<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=508s" target="_blank" rel="noopener">8:28</a>–<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=559s" target="_blank" rel="noopener">9:19</a>), (<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=604s" target="_blank" rel="noopener">10:04</a>–<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=617s" target="_blank" rel="noopener">10:17</a>), (<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=799s" target="_blank" rel="noopener">13:19</a>–<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=812s" target="_blank" rel="noopener">13:32</a>)</li></ul><div class="sh">How Anthropic reviews 30,000 changes a day</div><ul><li><strong>The workflow:</strong> Claude does a first-pass review and must try the change like a real user: end-to-end runs, opening it in a browser, linting and other checks. Hooks run on every edit and study the diffs so the PR gets corrected quickly, and Anthropic also uses its own code review product. The Claude.ai refresh, which tripled its performance, took about 3,000 PRs in a short time (<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=373s" target="_blank" rel="noopener">6:13</a>–<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=449s" target="_blank" rel="noopener">7:29</a>)</li><li><strong>Codify taste, check evidence:</strong> Teams should write their best practices and taste into a shared `CLAUDE.md` or `AGENTS.md` the agent consults during review. People then check the agent&#39;s evidence, such as a video of it clicking through a UI or screenshots of mobile and desktop views (<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=449s" target="_blank" rel="noopener">7:29</a>–<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=500s" target="_blank" rel="noopener">8:20</a>)</li><li><strong>Which tests matter:</strong> Saying &quot;just verify&quot; isn&#39;t enough. Anthropic leans on end-to-end tests, property tests and visual verification tests, and Osmani says good verification can easily double or triple outcome quality (<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=309s" target="_blank" rel="noopener">5:09</a>–<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=327s" target="_blank" rel="noopener">5:27</a>), (<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=563s" target="_blank" rel="noopener">9:23</a>–<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=602s" target="_blank" rel="noopener">10:02</a>)</li><li><strong>Sonar&#39;s layers (repeat):</strong> A deterministic layer for bugs and security issues like SQL injection, an agentic review layer for logic and intent issues, and a supply-chain layer for CVEs and malicious packages, run inside every loop: the agent loop, CI and maintenance (<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=701s" target="_blank" rel="noopener">11:41</a>–<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=795s" target="_blank" rel="noopener">13:15</a>)</li><li><strong>Enterprise worries:</strong> Companies that let teams experiment ended up with hundreds or thousands of agents touching systems and data. The three big concerns are control, permissions and the sandbox, which Sonar calls &quot;guide rails&quot; rather than guardrails (<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=817s" target="_blank" rel="noopener">13:37</a>–<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=878s" target="_blank" rel="noopener">14:38</a>)</li></ul><div class="sh">Lightning round</div><ul><li><strong>Quick answers:</strong> By end of 2027 most teams will run &quot;light factories with some dark corners&quot;. Agent-written PRs should be labelled (Kapur says for at least the next 6–9 months, for auditability), but a named human still owns each change. A PR is safe to merge when you&#39;re confident nothing will go wrong or you&#39;ve mitigated it as far as possible (<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=899s" target="_blank" rel="noopener">14:59</a>–<a href="https://www.youtube.com/watch?v=AnsXWH2_EBU&amp;t=1059s" target="_blank" rel="noopener">17:39</a>)</li></ul></div></article><article class="it full" id="v-UW8Qkk7MG8A" data-title="AI That Hunts Logic Bugs Before Attackers Do - Taylor Luttrell-Williams, Sonar" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=UW8Qkk7MG8A" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+I+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=UW8Qkk7MG8A" target="_blank" rel="noopener">AI That Hunts Logic Bugs Before Attackers Do - Taylor Luttrell-Williams, Sonar</a></h3><div class="meta">AI Engineer · Taylor Luttrell-Williams, Sonar · uploaded 29 Oct, 12:30 AM IST · 14:10</div><div class="verdict v-skim"><b>Verdict:</b> skim from 8:35 — a product demo, but the demo findings (8:35–12:21) show the kind of bug it catches.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 24 times before. New here: a product aimed at intent and logic bugs rather than code patterns, plus the OpenAI Daybreak partnership.</div><div class="repeat">🔁 Repeat: &#39;security&#39; — seen 4 times before. New here: a concrete demo with real findings.</div><div class="sh">Why pattern scanners miss these bugs</div><ul><li><strong>Intent bugs:</strong> Pattern-based static scanners (SAST) can&#39;t catch code that is valid but whose intent is flawed, such as broken access control, business logic gaps and authentication holes. Pentests happen at most twice a year or once a quarter, far slower than agents ship code (<a href="https://www.youtube.com/watch?v=UW8Qkk7MG8A&amp;t=46s" target="_blank" rel="noopener">0:46</a>–<a href="https://www.youtube.com/watch?v=UW8Qkk7MG8A&amp;t=161s" target="_blank" rel="noopener">2:41</a>)</li></ul><div class="sh">How Hunter Agent works</div><ul><li><strong>Pipeline:</strong> One agent maps the whole repository, then three specialist agents run, one per issue class. Adversarial validation and &quot;noise gates&quot; weed out false positives and by-design behaviour, and each finding gets a severity, impact and exact location (<a href="https://www.youtube.com/watch?v=UW8Qkk7MG8A&amp;t=161s" target="_blank" rel="noopener">2:41</a>–<a href="https://www.youtube.com/watch?v=UW8Qkk7MG8A&amp;t=223s" target="_blank" rel="noopener">3:43</a>)</li><li><strong>OpenAI Daybreak:</strong> Sonar announced it&#39;s joining the OpenAI Daybreak cyber partner program, giving governed access to frontier cybersecurity models inside Hunter Agent. Sonar pitches it as a second layer next to its existing SAST and dependency scanning (<a href="https://www.youtube.com/watch?v=UW8Qkk7MG8A&amp;t=272s" target="_blank" rel="noopener">4:32</a>–<a href="https://www.youtube.com/watch?v=UW8Qkk7MG8A&amp;t=372s" target="_blank" rel="noopener">6:12</a>)</li></ul><div class="sh">Live demo</div><ul><li><strong>The scan:</strong> In SonarQube Cloud (also works on self-hosted SonarQube Server) a &quot;scan now&quot; button estimates the units needed. A scan of his Python app took about an hour: clone, threat model, deep scans for insecure direct object references, broken access control and logic bugs, then deduplicated findings exported to the normal issue list (<a href="https://www.youtube.com/watch?v=UW8Qkk7MG8A&amp;t=392s" target="_blank" rel="noopener">6:32</a>–<a href="https://www.youtube.com/watch?v=UW8Qkk7MG8A&amp;t=504s" target="_blank" rel="noopener">8:24</a>)</li><li><strong>What it found:</strong> 46 open issues across broken access control, business logic and authentication/session. Examples: any signed-in user could pass the admin check because they could write their own role field, and a user with only a password could reach every protected route, including admin, without finishing MFA (<a href="https://www.youtube.com/watch?v=UW8Qkk7MG8A&amp;t=515s" target="_blank" rel="noopener">8:35</a>–<a href="https://www.youtube.com/watch?v=UW8Qkk7MG8A&amp;t=741s" target="_blank" rel="noopener">12:21</a>)</li><li><strong>Workflow:</strong> Findings can be accepted, confirmed (which affects the quality gate) or marked false positive. Scans can run on demand or daily, weekly or monthly on a chosen branch, and from this week a SonarQube remediation agent can fix these issues automatically (<a href="https://www.youtube.com/watch?v=UW8Qkk7MG8A&amp;t=656s" target="_blank" rel="noopener">10:56</a>–<a href="https://www.youtube.com/watch?v=UW8Qkk7MG8A&amp;t=823s" target="_blank" rel="noopener">13:43</a>)</li></ul></div></article><article class="it full" id="v-P_0_Th_ZzIg" data-title="Stop Guessing Your vLLM Config: Benchmarking LLMs on Runpod - Chris Vela, Runpod" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=P_0_Th_ZzIg" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+P+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg" target="_blank" rel="noopener">Stop Guessing Your vLLM Config: Benchmarking LLMs on Runpod - Chris Vela, Runpod</a></h3><div class="meta">AI Engineer · Chris Vela, forward-deployed engineer, Runpod · uploaded 28 Oct, 2:30 PM IST · 16:29</div><div class="verdict v-skim"><b>Verdict:</b> skim from 10:02 — the batch-token benchmark (10:02–11:17) and the cost advice at the end are the useful parts; BenchPod isn&#39;t out yet.</div><div class="repeat">🔁 Repeat: &#39;inference / serving&#39; — seen 34 times before. New here: a hands-on tuning result for vLLM&#39;s max batch tokens on Kimi K3.</div><div class="repeat">🔁 Repeat: &#39;open source / local models&#39; — seen 45 times before. New here: Runpod&#39;s internal experience self-hosting Kimi K3, DeepSeek and others for about 50 staff.</div><div class="repeat">🔁 Repeat: &#39;LLM releases / benchmarks&#39; — seen 43 times before. New here: little; the focus is benchmarking your own config, not model leaderboards.</div><div class="repeat">🔁 Repeat: &#39;GPU compute markets&#39; — seen 4 times before. New here: a B200 node costs about $40K a month on Runpod.</div><div class="sh">Why people get vLLM wrong</div><ul><li><strong>Start from the use case:</strong> People copy the default vLLM recipe, run the wrong vLLM version (not nightly) or the wrong context size. Ask first whether it&#39;s a coding agent or simple summaries, and how many concurrent users, since that drives KV cache use (<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=95s" target="_blank" rel="noopener">1:35</a>–<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=158s" target="_blank" rel="noopener">2:38</a>)</li><li><strong>Version and CUDA gotchas:</strong> Kimi K3 won&#39;t run on vLLM 0.27, and it works on CUDA 13.0 but not 12.8. He wouldn&#39;t put a model in production the day after release because of hallucinations in early builds (<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=179s" target="_blank" rel="noopener">2:59</a>–<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=221s" target="_blank" rel="noopener">3:41</a>), (<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=419s" target="_blank" rel="noopener">6:59</a>–<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=432s" target="_blank" rel="noopener">7:12</a>)</li></ul><div class="sh">BenchPod</div><ul><li><strong>What it is:</strong> A Runpod template (due at the end of the month) built on the vLLM OpenAI-compatible image. It runs a FastAPI app with metrics, a self-healing watchdog and live config changes without a full restart, avoiding a roughly 30-minute weight download each time (<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=227s" target="_blank" rel="noopener">3:47</a>–<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=336s" target="_blank" rel="noopener">5:36</a>)</li><li><strong>In production internally:</strong> Kimi K3 runs on four nodes for about 50 internal users. When a GPU failed last Sunday it self-healed with about a 9-minute cold start and no user noticed. On a B300 you can use only about half of Kimi K3&#39;s 1M context (<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=339s" target="_blank" rel="noopener">5:39</a>–<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=400s" target="_blank" rel="noopener">6:40</a>), (<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=574s" target="_blank" rel="noopener">9:34</a>–<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=589s" target="_blank" rel="noopener">9:49</a>), (<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=748s" target="_blank" rel="noopener">12:28</a>–<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=772s" target="_blank" rel="noopener">12:52</a>)</li><li><strong>The benchmark result:</strong> Tests at 1, 8, 64 and 192 concurrent users showed that raising max batch tokens barely changed time to first token but cut inter-token latency noticeably, so long jobs finish faster than with the stock recipe (<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=602s" target="_blank" rel="noopener">10:02</a>–<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=677s" target="_blank" rel="noopener">11:17</a>)</li></ul><div class="sh">Takeaways</div><ul><li><strong>Process:</strong> Pick a pod and GPU, compare configs, test with your agent, optimise for the metric you care about (inter-token latency, time to first token or time per output token), then ship the winner to serverless or multi-node (<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=813s" target="_blank" rel="noopener">13:33</a>–<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=848s" target="_blank" rel="noopener">14:08</a>)</li><li><strong>You may not need a frontier model:</strong> A B200 node costs about $40K a month. He runs DeepSeek on 4× H200 with good results and keeps Kimi for long, detailed tasks (<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=864s" target="_blank" rel="noopener">14:24</a>–<a href="https://www.youtube.com/watch?v=P_0_Th_ZzIg&amp;t=923s" target="_blank" rel="noopener">15:23</a>)</li></ul></div></article><article class="it full" id="v-58ulJViGFgU" data-title="Who Is Making This Request? Agent Auth 101 - Kamil Potrec, Keycard" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=58ulJViGFgU" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=58ulJViGFgU" target="_blank" rel="noopener">Who Is Making This Request? Agent Auth 101 - Kamil Potrec, Keycard</a></h3><div class="meta">AI Engineer · Kamil Potrec, product team, Keycard · uploaded 28 Oct, 1:30 PM IST · 18:35</div><div class="verdict v-skim"><b>Verdict:</b> skim from 11:16 — the SDK and gateway tradeoffs (11:16–16:21) are worth a look; the rest overlaps the two earlier Keycard talks.</div><div class="repeat">🔁 Repeat: &#39;agent security&#39; — seen 24 times before. New here: the clearest comparison so far of SDKs versus gateways for keeping credentials away from agents.</div><div class="repeat">🔁 Repeat: &#39;agent identity&#39; — seen 6 times before (this is Keycard&#39;s third talk). New here: a checklist of what a full agent auth system needs.</div><div class="repeat">🔁 Repeat: &#39;secrets management&#39; — seen 8 times before. New here: gateway-injected credentials with instant revocation.</div><div class="repeat">🔁 Repeat: &#39;AI gateway&#39; — seen 6 times before. New here: an honest list of gateway downsides.</div><div class="repeat">🔁 Repeat: &#39;agent auth&#39; — seen 4 times before. New here: agentbaseline.org reference implementation.</div><div class="repeat">🔁 Repeat: &#39;MCP servers&#39; — seen 35 times before. New here: only the auth angle.</div><div class="sh">How agents get credentials today</div><ul><li><strong>The usual setup (repeat):</strong> Users hand agents personal access tokens, agents hold their own static model API keys, and MCP servers fronting internal APIs use over-privileged service accounts. The MCP server can&#39;t tell whether a request came from Alice&#39;s CLI or her agent (<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=62s" target="_blank" rel="noopener">1:02</a>–<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=176s" target="_blank" rel="noopener">2:56</a>)</li><li><strong>Why it breaks:</strong> In his invoicing example, an agent asked to look at a recent invoice decides, maliciously or just helpfully, to send it, and nothing shows whether Alice or the agent made that call. Tokens aren&#39;t attributed, are hard to revoke and pile up in agents. He compares agents to the office prank of posting &quot;I&#39;m buying donuts&quot; from an unlocked laptop, except agents do it all the time (<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=186s" target="_blank" rel="noopener">3:06</a>–<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=312s" target="_blank" rel="noopener">5:12</a>)</li></ul><div class="sh">What proper agent auth needs</div><ul><li><strong>OAuth for agents:</strong> Services advertise how to get access, clients request it, and agents get dynamic credentials scoped to one interaction and tool. Agents should authenticate first, using workload identity federation, private keys, certificates or URL-based auth; the mechanism matters less than doing it (<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=315s" target="_blank" rel="noopener">5:15</a>–<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=427s" target="_blank" rel="noopener">7:07</a>)</li><li><strong>The requirements list:</strong> Per-agent (even per-session) identity separate from whoever launched it, delegation rules for who can act for whom, short-lived scoped credentials with no master key, federated trust across hundreds of existing systems, a broker that swaps legacy credentials just in time, policies for which actions need human approval, and an audit log (<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=430s" target="_blank" rel="noopener">7:10</a>–<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=590s" target="_blank" rel="noopener">9:50</a>)</li></ul><div class="sh">SDKs versus gateways</div><ul><li><strong>Why SDKs fall short:</strong> They need full adoption, a version per language, can&#39;t change tools you don&#39;t control like Claude Code or Codex, and bug fixes mean tracking every consumer. Worst of all, the credential still lives in the agent&#39;s environment, and agents are persistent at getting around controls (<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=676s" target="_blank" rel="noopener">11:16</a>–<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=766s" target="_blank" rel="noopener">12:46</a>)</li><li><strong>Gateways:</strong> Credentials move to a vault, and a gateway authenticates the agent, checks policy and injects the credential into the request. That gives instant revocation, request-level limits (read email but not send), and observability without changing downstream services (<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=766s" target="_blank" rel="noopener">12:46</a>–<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=896s" target="_blank" rel="noopener">14:56</a>)</li><li><strong>Gateway costs:</strong> Extra latency, agents must be forced through it with network controls, no help for local tool execution or the identity problem, a single high-value target, TLS interception headaches, and someone has to configure and run routes and policies (<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=896s" target="_blank" rel="noopener">14:56</a>–<a href="https://www.youtube.com/watch?v=58ulJViGFgU&amp;t=981s" target="_blank" rel="noopener">16:21</a>)</li></ul></div></article><article class="it full" id="v-xZX3pmaB8Hk" data-title="Exploits Now Beat Patches: Open Source Security in the AI Era - Patrick Smyth, Chainguard" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=xZX3pmaB8Hk" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+T+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk" target="_blank" rel="noopener">Exploits Now Beat Patches: Open Source Security in the AI Era - Patrick Smyth, Chainguard</a></h3><div class="meta">AI Engineer · Patrick Smyth, Chainguard · uploaded 28 Oct, 12:30 PM IST · 21:47</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — the attack data (1:05–6:44) and the agent-skills figures (19:17–20:08) are new and concrete, though the second half is Chainguard&#39;s product pitch.</div><div class="repeat">🔁 Repeat: &#39;agent skills&#39; — seen 14 times before. New here: his analysis that about 5% of upstream agent skills are actively malicious and 30–40% have serious security problems.</div><div class="repeat">🔁 Repeat: &#39;AI supply chain security&#39; — seen 5 times before. New here: this year&#39;s malware waves and Mandiant&#39;s exploit-before-patch numbers.</div><div class="repeat">🔁 Repeat: &#39;security&#39; — seen 4 times before. New here: a plain list of what to do this year.</div><div class="sh">The threat picture</div><ul><li><strong>AI levels up attackers:</strong> A 17-year-old in Osaka used ChatGPT-written scripts to take about 4.4 million records from Japan&#39;s biggest internet cafe chain. FunkSec hit 85 targets, and one unidentified attacker used Claude Code against 17 organisations, from writing ransom notes to picking targets. Everyone moves &quot;a level up&quot; in threat (<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=65s" target="_blank" rel="noopener">1:05</a>–<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=153s" target="_blank" rel="noopener">2:33</a>)</li><li><strong>Exploits now come first:</strong> Per Mandiant&#39;s M-Trends report, in 2018–19 the patch came 63 days before exploitation on average. Now it&#39;s minus 70 days, so exploits land before the patch, and 30-day remediation windows &quot;may as well be a million years&quot; (<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=153s" target="_blank" rel="noopener">2:33</a>–<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=298s" target="_blank" rel="noopener">4:58</a>)</li><li><strong>Malware waves:</strong> The Shai-Hulud npm worm spawned copycats. Trivy (a scanner) and LiteLLM were hit, and the Axios compromise was live for only 2 hours but got 600,000 downloads; three of these were in March. Attacks chain because everyone shares dependencies (<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=298s" target="_blank" rel="noopener">4:58</a>–<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=404s" target="_blank" rel="noopener">6:44</a>)</li></ul><div class="sh">What to do this year</div><ul><li><strong>Checklist:</strong> Add cooldown periods for new packages, remediate CVEs faster than ever, sign artifacts with SLSA and Sigstore, lock down developer laptops including physical keys, and finish containerisation, CI/CD and golden-image projects now (<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=544s" target="_blank" rel="noopener">9:04</a>–<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=650s" target="_blank" rel="noopener">10:50</a>)</li><li><strong>Four attack surfaces:</strong> Malware (helped by cooldowns), known CVEs (still must be fixed because they&#39;re in public databases), zero days (frontier models like Mythos and OpenAI&#39;s Daybreak chain small bugs into exploits), and side doors: CI/CD, developer workstations and the new agent layer (<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=685s" target="_blank" rel="noopener">11:25</a>–<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=829s" target="_blank" rel="noopener">13:49</a>)</li></ul><div class="sh">Chainguard&#39;s approach</div><ul><li><strong>Products:</strong> Containers with no known vulnerabilities on its Wolfi rolling distro, rebuilt one to four times a day with an SLA of 1 day for known-exploited bugs, 7 for criticals and 14 for the rest. Chainguard Libraries rebuild PyPI, npm and Maven packages from clean source, Athena is a bank-led consortium that shares zero days, and hardened Chainguard Actions replace GitHub Actions (<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=837s" target="_blank" rel="noopener">13:57</a>–<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=1022s" target="_blank" rel="noopener">17:02</a>), (<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=1073s" target="_blank" rel="noopener">17:53</a>–<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=1147s" target="_blank" rel="noopener">19:07</a>)</li><li><strong>Sign everything:</strong> Sign every artifact when it&#39;s created with Sigstore, attach signed SLSA provenance, and check it at each internal pipeline step, since most attacks happen between source and distribution (<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=1022s" target="_blank" rel="noopener">17:02</a>–<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=1068s" target="_blank" rel="noopener">17:48</a>)</li><li><strong>Hardened agent skills:</strong> Chainguard hardens upstream third-party skills through deterministic and agentic checks, and organisations can upload their own. His figures: about 5% of upstream skills are actively malicious (around 20% earlier this year) and another 30–40% have serious security issues (<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=1157s" target="_blank" rel="noopener">19:17</a>–<a href="https://www.youtube.com/watch?v=xZX3pmaB8Hk&amp;t=1208s" target="_blank" rel="noopener">20:08</a>)</li></ul></div></article><article class="it full" id="v-SbwckhZkPGs" data-title="NVIDIA&#39;s New AI Sandbox Does More Than Docker (Openshell)" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=SbwckhZkPGs" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+B+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=SbwckhZkPGs" target="_blank" rel="noopener">NVIDIA&#39;s New AI Sandbox Does More Than Docker (Openshell)</a></h3><div class="meta">Better Stack · Josh, Better Stack · uploaded 28 Oct, 7:30 PM IST · 7:48</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a short, concrete demo, and the per-request rules are new even though agent sandboxes are well-covered ground.</div><div class="repeat">🔁 Repeat: &#39;sandboxes for agents&#39; — seen 19 times before. New here: per-binary, per-request network rules and a Z3 solver that checks what a policy change would grant.</div><div class="repeat">🔁 Repeat: &#39;agent security&#39; — seen 24 times before. New here: NVIDIA&#39;s usage numbers.</div><div class="repeat">🔁 Repeat: &#39;secrets management&#39; — seen 8 times before. New here: credentials injected outside the sandbox, the same idea as Keycard&#39;s gateway talk today.</div><div class="repeat">🔁 Repeat: &#39;prompt injection&#39; — seen 5 times before. New here: only the point that an injected agent has no key to leak.</div><div class="sh">What OpenShell adds over Docker</div><ul><li><strong>The problem:</strong> A container stops an agent wandering around your machine, but once it has a GitHub token it can&#39;t tell reading a repo from opening issues; it&#39;s all traffic to the same address (<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=61s" target="_blank" rel="noopener">1:01</a>)</li><li><strong>How it works:</strong> OpenShell is open source (Apache 2.0, in Rust). A gateway you talk to, a trusted supervisor that makes every decision, and a sandbox whose only exit runs through the supervisor. Every file access, system call and network connection is checked against a policy, and it runs on Docker, Podman, Kubernetes or a small microVM (<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=61s" target="_blank" rel="noopener">1:01</a>–<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=91s" target="_blank" rel="noopener">1:31</a>), (<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=265s" target="_blank" rel="noopener">4:25</a>–<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=274s" target="_blank" rel="noopener">4:34</a>)</li></ul><div class="sh">Demo on a Mac</div><ul><li><strong>File and process limits:</strong> The sandbox runs unprivileged, can&#39;t escalate, and writes outside allowed paths are denied at the kernel level. These rules are fixed at start-up and the agent can&#39;t weaken them (<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=99s" target="_blank" rel="noopener">1:39</a>–<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=141s" target="_blank" rel="noopener">2:21</a>)</li><li><strong>Network rules:</strong> By default nothing is reachable and every denial is logged. He adds a rule letting `curl` read the GitHub API without restarting, and a POST to create an issue is still denied because rules are tied to the binary and action (<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=141s" target="_blank" rel="noopener">2:21</a>–<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=217s" target="_blank" rel="noopener">3:37</a>)</li><li><strong>Credential injection and policy checks:</strong> The agent never sees real keys; the supervisor adds them only on approved requests and resolves DNS itself. Before a policy change goes live, a Z3 solver works out what new access it would grant, catching a stray wildcard, with a 10-second default limit (<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=217s" target="_blank" rel="noopener">3:37</a>–<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=299s" target="_blank" rel="noopener">4:59</a>)</li></ul><div class="sh">Numbers and caveats</div><ul><li><strong>Adoption:</strong> Public since February and announced at GTC in March with Cisco, CrowdStrike, Google Cloud and Microsoft Security. It has over 20,000 GitHub stars, and NVIDIA&#39;s own telemetry says it created 550,000+ sandboxes and denied 4.2 million agent actions in two weeks this summer (<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=299s" target="_blank" rel="noopener">4:59</a>–<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=331s" target="_blank" rel="noopener">5:31</a>)</li><li><strong>Compared with others:</strong> Docker, Firecracker and Apple&#39;s container are walls that OpenShell sits on. Anthropic&#39;s sandbox runtime is lighter per-process limits, while E2B and Daytona are hosted throwaway sandboxes; OpenShell is self-hosted and policy-first for agents that run for hours (<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=335s" target="_blank" rel="noopener">5:35</a>–<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=365s" target="_blank" rel="noopener">6:05</a>)</li><li><strong>Caveats:</strong> Telemetry is on by default (one environment variable turns it off). On a Mac it needs Docker Desktop&#39;s VM with Landlock and host networking, and its doctor command shows green either way. About 12% of sandbox creations failed in NVIDIA&#39;s own data, and it&#39;s only at version 0.1.5. For a quick Claude Code sandbox, Anthropic&#39;s runtime or plain containers is less work (<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=369s" target="_blank" rel="noopener">6:09</a>–<a href="https://www.youtube.com/watch?v=SbwckhZkPGs&amp;t=442s" target="_blank" rel="noopener">7:22</a>)</li></ul></div></article></div>',1))])}const V=w(A,[["render",U]]);export{X as __pageData,V as default};
